module.render:
const esc = (s) => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
// Fall back to identity if an older app build doesn't pass resolve().
const R = (typeof resolve === 'function') ? resolve : (p) => p;
const src = (args.src || '').trim();
const trigger = String(args.trigger || 'click').toLowerCase() === 'auto' ? 'auto' : 'click';
const loop = String(args.loop) === 'true';
const muted = String(args.muted) === 'true';
const controls = String(args.controls) === 'true';
let width = parseFloat(args.width); if (!Number.isFinite(width) || width <= 0) width = 480;

if (!src) return '\n\n<div class="mdp-mod-video mdp-video-empty">（@video: src に動画ファイルのパスか YouTube URL を指定）</div>\n\n';

const yt = src.match(/(?:youtube\.com\/(?:watch\?v=|embed\/|shorts\/)|youtu\.be\/)([A-Za-z0-9_-]{6,})/);
let inner, kind;
if (yt) {
  kind = 'yt';
  const id = yt[1];
  const p = ['enablejsapi=1', 'playsinline=1', 'rel=0', 'modestbranding=1'];
  if (trigger === 'auto') p.push('autoplay=1');
  if (muted || trigger === 'auto') p.push('mute=1');
  if (loop) p.push('loop=1', 'playlist=' + id);
  p.push('controls=' + (controls ? '1' : '0'));
  const url = 'https://www.youtube.com/embed/' + id + '?' + p.join('&');
  inner = '<iframe class="mdp-video-frame" src="' + esc(url) + '" frameborder="0" allow="autoplay; encrypted-media; picture-in-picture; fullscreen" allowfullscreen></iframe>';
} else {
  kind = 'file';
  const attrs = ['class="mdp-video-el"', 'playsinline', 'preload="auto"'];
  if (controls) attrs.push('controls');
  if (loop) attrs.push('loop');
  if (muted) attrs.push('muted');
  // resolve() (provided by the app) maps a deck-relative path / @alias / URL to a
  // served URL, so the <video> can load a local file directly.
  inner = '<video ' + attrs.join(' ') + ' src="' + esc(R(src)) + '"></video>';
}
const overlay = (kind === 'yt' ? (trigger === 'click') : !controls)
  ? '<div class="mdp-video-play" aria-hidden="true"><div class="mdp-video-play-btn">▶</div></div>'
  : '';

return '\n\n<div class="mdp-mod-video mdp-interactive" data-kind="' + kind + '" data-trigger="' + trigger + '" data-controls="' + (controls ? '1' : '0') + '" style="--vid-w:' + width + 'px;">' + inner + overlay + '</div>\n\n';

module.script:
export default {
  init(el, ctx) {
    const trigger = el.dataset.trigger === 'auto' ? 'auto' : 'click';
    const controls = el.dataset.controls === '1';
    const overlay = el.querySelector('.mdp-video-play');
    const showOv = () => { if (overlay) overlay.style.display = 'flex'; };
    const hideOv = () => { if (overlay) overlay.style.display = 'none'; };
    const video = el.querySelector('video');
    const iframe = el.querySelector('iframe');

    const isOwner = ctx.role === 'owner';
    const OWNERS = window.__mdpVideoOwners || (window.__mdpVideoOwners = {});
    const me = { presenting: !!ctx.presenting };
    if (isOwner) {
      const cur = OWNERS[ctx.syncId];
      if (!cur || me.presenting || !cur.presenting) OWNERS[ctx.syncId] = me;
    }
    const acting = () => {
      if (!isOwner) return false;
      if (!OWNERS[ctx.syncId]) OWNERS[ctx.syncId] = me;
      return OWNERS[ctx.syncId] === me;
    };
    let waiters = [];     // emit-wait replies to play / restart: sent when it ends
    const release = () => { const w = waiters; waiters = []; w.forEach((d) => d()); };
    const toSec = (v) => { const n = parseFloat(v); return Number.isFinite(n) && n >= 0 ? n : 0; };

    if (video) {
      if (!acting()) video.muted = true;
      const tryPlay = () => {
        const p = video.play();
        if (p && typeof p.then === 'function') {
          p.then(hideOv).catch(() => {
            // Autoplay with sound blocked → retry muted.
            video.muted = true;
            const q = video.play();
            if (q && typeof q.then === 'function') q.then(hideOv).catch(showOv);
          });
        } else { hideOv(); }
      };
      const publish = () => {
        if (acting()) ctx.setShared({ playing: !video.paused && !video.ended, t: video.currentTime || 0, at: Date.now() });
      };
      // A follower mirrors the owner's state (muted): play / pause, and the
      // position when it has drifted.
      const follow = (st) => {
        if (!st || acting()) return;
        const want = st.playing ? toSec(st.t) + (Date.now() - (st.at || Date.now())) / 1000 : toSec(st.t);
        if (Math.abs((video.currentTime || 0) - want) > 0.5) { try { video.currentTime = want; } catch (e) {} }
        if (st.playing && (video.paused || video.ended)) { video.muted = true; tryPlay(); }
        else if (!st.playing && !video.paused) video.pause();
      };
      const toggle = () => { if (video.paused || video.ended) tryPlay(); else video.pause(); };
      const onClick = (e) => {
        if (e) e.stopPropagation();
        if (acting()) toggle(); else ctx.sendAction('toggle');
      };
      const onPlay = () => { hideOv(); publish(); };
      const onPause = () => { if (!controls) showOv(); publish(); };
      const onEnded = () => { if (!controls) showOv(); publish(); release(); };
      const onSeeked = () => publish();
      if (!controls) el.addEventListener('click', onClick);
      video.addEventListener('play', onPlay);
      video.addEventListener('pause', onPause);
      video.addEventListener('ended', onEnded);
      video.addEventListener('seeked', onSeeked);
      ctx.onShared(follow);

      if (isOwner) {
        ctx.onAction((type) => { if (acting() && type === 'toggle') toggle(); });
        ctx.onCommand((action, args, done) => {
          if (!acting()) return;           // the acting instance replies
          const a = action || 'play';
          if (a === 'play' || a === 'restart') {
            if (a === 'restart') { try { video.currentTime = 0; } catch (e) {} }
            if (video.loop) done(); else waiters.push(done);
            tryPlay();
          } else if (a === 'pause') { video.pause(); done(); }
          else if (a === 'stop') { video.pause(); try { video.currentTime = 0; } catch (e) {} release(); done(); }
          else if (a === 'toggle') { toggle(); done(); }
          else if (a === 'seek') { try { video.currentTime = toSec(args[0]); } catch (e) {} done(); }
          else if (a === 'mute' || a === 'unmute') { video.muted = a === 'mute'; done(); }
          else done();
        });
      }

      if (acting()) {
        ctx.setShared({ playing: false, t: 0, at: Date.now() });
        if (trigger === 'auto') tryPlay();
        else if (!controls) showOv();
      } else {
        if (!controls) showOv();
        follow(ctx.getShared());
      }
      ctx.onCleanup(() => {
        if (!controls) el.removeEventListener('click', onClick);
        video.removeEventListener('play', onPlay);
        video.removeEventListener('pause', onPause);
        video.removeEventListener('ended', onEnded);
        video.removeEventListener('seeked', onSeeked);
        const wasActing = acting();
        try { video.pause(); video.currentTime = 0; } catch (e) {}
        release();
        if (wasActing) {
          ctx.setShared({ playing: false, t: 0, at: Date.now() });   // not playing when the slide returns
          if (OWNERS[ctx.syncId] === me) delete OWNERS[ctx.syncId];
        }
      });
    } else if (iframe) {
      const post = (func, args) => {
        try { if (iframe.contentWindow) iframe.contentWindow.postMessage(JSON.stringify({ event: 'command', func: func, args: args || [] }), '*'); } catch (e) {}
      };
      let playing = false;
      const setPlaying = (on, t) => {
        playing = on;
        if (on) hideOv(); else if (trigger === 'click' && overlay) showOv();
        if (acting()) ctx.setShared({ playing: on, t: typeof t === 'number' ? t : null, at: Date.now() });
      };
      // A follower mirrors play / pause / seek, muted (the player accepts commands
      // only once it has loaded, so the mute is repeated then).
      const muteSoon = () => { if (!acting()) { post('mute'); setTimeout(() => post('mute'), 1500); } };
      const follow = (st) => {
        if (!st || acting()) return;
        post('mute');
        if (typeof st.t === 'number') post('seekTo', [st.t, true]);
        if (st.playing) { hideOv(); post('playVideo'); } else post('pauseVideo');
        playing = !!st.playing;
      };
      const toggle = () => { if (playing) { post('pauseVideo'); setPlaying(false); } else { post('playVideo'); setPlaying(true); } };
      const onOverlay = (e) => { e.stopPropagation(); if (acting()) toggle(); else ctx.sendAction('toggle'); };
      const onLoad = () => muteSoon();
      iframe.addEventListener('load', onLoad);
      ctx.onShared(follow);
      if (isOwner) {
        ctx.onAction((type) => { if (acting() && type === 'toggle') toggle(); });
        ctx.onCommand((action, args, done) => {
          if (!acting()) return;
          const a = action || 'play';
          if (a === 'play') { post('playVideo'); setPlaying(true); }
          else if (a === 'restart') { post('seekTo', [0, true]); post('playVideo'); setPlaying(true, 0); }
          else if (a === 'pause') { post('pauseVideo'); setPlaying(false); }
          else if (a === 'stop') { post('pauseVideo'); post('seekTo', [0, true]); setPlaying(false, 0); }
          else if (a === 'toggle') toggle();
          else if (a === 'seek') { const t = toSec(args[0]); post('seekTo', [t, true]); setPlaying(playing, t); }
          else if (a === 'mute') post('mute');
          else if (a === 'unmute') post('unMute');
          done();
        });
      }
      if (trigger === 'click' && overlay) {
        showOv();
        overlay.addEventListener('click', onOverlay);
      } else {
        hideOv();
        playing = trigger === 'auto';
      }
      if (acting()) ctx.setShared({ playing: playing, t: null, at: Date.now() });
      else { muteSoon(); follow(ctx.getShared()); }
      ctx.onCleanup(() => {
        iframe.removeEventListener('load', onLoad);
        if (overlay) overlay.removeEventListener('click', onOverlay);
        post('pauseVideo');
        if (acting()) {
          ctx.setShared({ playing: false, t: null, at: Date.now() });
          if (OWNERS[ctx.syncId] === me) delete OWNERS[ctx.syncId];
        }
      });
    }
  }
}
